// The factory's build: runs every design (skyscrapers.ts, village.ts, vehicles.ts and the
// families listed in FAMILIES below) and writes the export
// folder -- gitignored, regenerated by every `pnpm build`:
//
//   export/glb/<id>.glb             the model
//   export/thumbs/<id>.png          a 512 px thumbnail (renderGlbThumb.ts)
//   export/js/<id>.js               the model as one standalone JS file, build(THREE)
//                                   returning a THREE.Group (jsModel.ts)
//   export/tree/<id>.json           the procedural source tree, for the site only
//                                   (sourceTree.ts)
//   export/refs/<id>/...            the design's source images, copied from
//                                   assets/<references>/, for the site only
//   export/skyscrapers.meta.json    the buildings' catalog entries (skyscrapers, landmarks,
//                                   stations), for the game to import
//   export/village.meta.json        the village houses' catalog entries, likewise
//   export/vehicles.meta.json       the vehicles' catalog entries, likewise
//   export/catalog.json             what the site lists (catalog.ts)
//
// The same folder is Vite's publicDir, so the site serves it as it stands.
//
// The output is deterministic (materials in name order, no timestamps): an
// unchanged design produces byte-identical GLBs and its thumbnail -- the slow
// part -- is not re-rendered. Files of a design that no longer exists are deleted.
//
// A design with z-fighting faces (coplanar.ts) fails the build before anything
// is written: the deploy does not wait for the tests, so this is what keeps a
// flickering model off the site and out of the export.
//
//   pnpm build:models
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { PNG } from "pngjs";
import { renderGlbThumb } from "./renderGlbThumb.ts";
import { SKYSCRAPERS, SKYSCRAPER_CATALOG } from "./skyscrapers.ts";
import { VEHICLES, VEHICLE_CATALOG } from "./vehicles.ts";
import { CHURCHES } from "./churches.ts";
import { CATHEDRALS } from "./cathedrals.ts";
import { LANDMARKS } from "./landmarks.ts";
import { STATIONS } from "./stations.ts";
import { AIRCRAFT } from "./aircraft.ts";
import { SHIPS } from "./ships.ts";
import { EMU471_DESIGNS } from "./emu471.ts";
import { EMU680_DESIGNS } from "./emu680.ts";
import { CABLE_CABINS } from "./cableCabins.ts";
import { TRUCKS } from "./trucks.ts";
import { STEAM_LOCOS } from "./steamLocos.ts";
import { CZ_ELECTRICS } from "./czElectrics.ts";
import { MAINLINE_ELECTRICS } from "./mainlineElectrics.ts";
import { CITY_BUS_DESIGNS, KAROSA_DESIGNS } from "./buses.ts";
import { VILLAGE_HOUSES } from "./village.ts";
import type { ProceduralDesign } from "./design.ts";
import { glbStats } from "./glbStats.ts";
import { JS_DIR, bundleDesign, gzipSize, writeIfChanged } from "./jsModel.ts";
import { findCoplanarOverlaps, type CoplanarOverlap } from "./coplanar.ts";
import {
  CATALOG_FILE, META_FILE, REFERENCE_EXTENSIONS, REFS_DIR, VEHICLE_META_FILE, VILLAGE_META_FILE, catalogRecord, exportMeta,
  exportVehicleMeta, metaEntry, type ModelCatalog, type ReferenceImage,
} from "./catalog.ts";
import { TREE_DIR, type SourceTree } from "./sourceTree.ts";
import type { MeshBuilder } from "./meshBuilder.ts";
import type { VehicleRig } from "./rig.ts";

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

/** The repository's reference material, one folder per model (ProceduralDesign.references). */
export const ASSETS_DIR = path.join(REPO_ROOT, "assets");

/** The export folder, and the site's publicDir. */
export const EXPORT_DIR = path.join(REPO_ROOT, "export");

/** Thumbnail size: the 512 px square the game's building thumbnails use. */
const THUMB_SIZE = 512;

/**
 * Every family of designs with the generator module that exports its build
 * functions (the JS bundle's entry) and the meta file it is listed in: the
 * buildings', the village houses' own, or the vehicles'.
 */
const FAMILIES: ReadonlyArray<{ designs: readonly ProceduralDesign[]; source: string; meta: "buildings" | "village" | "vehicles" }> = [
  { designs: SKYSCRAPERS, source: "skyscrapers.ts", meta: "buildings" },
  { designs: CHURCHES, source: "churches.ts", meta: "buildings" },
  { designs: CATHEDRALS, source: "cathedrals.ts", meta: "buildings" },
  { designs: LANDMARKS, source: "landmarks.ts", meta: "buildings" },
  { designs: STATIONS, source: "stations.ts", meta: "buildings" },
  { designs: VILLAGE_HOUSES, source: "village.ts", meta: "village" },
  { designs: VEHICLES, source: "vehicles.ts", meta: "vehicles" },
  { designs: STEAM_LOCOS, source: "steamLocos.ts", meta: "vehicles" },
  { designs: CZ_ELECTRICS, source: "czElectrics.ts", meta: "vehicles" },
  { designs: MAINLINE_ELECTRICS, source: "mainlineElectrics.ts", meta: "vehicles" },
  { designs: TRUCKS, source: "trucks.ts", meta: "vehicles" },
  { designs: KAROSA_DESIGNS, source: "karosa.ts", meta: "vehicles" },
  { designs: CITY_BUS_DESIGNS, source: "cityBuses.ts", meta: "vehicles" },
  { designs: AIRCRAFT, source: "aircraft.ts", meta: "vehicles" },
  { designs: SHIPS, source: "ships.ts", meta: "vehicles" },
  { designs: CABLE_CABINS, source: "cableCabins.ts", meta: "vehicles" },
  { designs: EMU471_DESIGNS, source: "emu471.ts", meta: "vehicles" },
  { designs: EMU680_DESIGNS, source: "emu680.ts", meta: "vehicles" },
];

/** Every building design: the skyscrapers, then the landmarks and stations (skyscrapers.meta.json). */
export const BUILDINGS: readonly ProceduralDesign[] = FAMILIES.filter((f) => f.meta === "buildings").flatMap((f) => f.designs);

/** Every vehicle design: road, rail, air, water and rope (vehicles.meta.json). */
export const ALL_VEHICLES: readonly ProceduralDesign[] = FAMILIES.filter((f) => f.meta === "vehicles").flatMap((f) => f.designs);

/** Every design, by id: the buildings, the village houses (village.meta.json), then the vehicles. */
export const DESIGNS: ReadonlyMap<string, ProceduralDesign> = new Map([...BUILDINGS, ...VILLAGE_HOUSES, ...ALL_VEHICLES].map((d) => [d.id, d]));

const VEHICLE_IDS = new Set(ALL_VEHICLES.map((d) => d.id));

/** The generator module that exports each design's build function (the JS bundle's entry). */
const DESIGN_SOURCE = new Map<string, string>(FAMILIES.flatMap((f) => f.designs.map((d) => [d.id, f.source] as const)));

/** The generator module exporting a design's build function. Throws on an unknown id. */
export function designSource(id: string): string {
  const source = DESIGN_SOURCE.get(id);
  if (!source) throw new Error(`no procedural model "${id}"`);
  return source;
}

/**
 * A built design's GLB bytes. The generator string is part of the bytes; a
 * skyscraper's matches what the webapp's copy wrote, so a model built here is
 * byte-identical to one built there.
 */
function toGlb(id: string, model: MeshBuilder): Uint8Array {
  return VEHICLE_IDS.has(id)
    ? model.toGlb(`Rail Island procedural vehicle (${id})`, "vehicle")
    : model.toGlb(`Rail Island procedural building (${id})`);
}

/** The GLB bytes of one design. Throws on an unknown id. */
export function designGlb(id: string): Uint8Array {
  const design = DESIGNS.get(id);
  if (!design) throw new Error(`no procedural model "${id}"`);
  return toGlb(id, design.build());
}

/** The procedural source tree of one design. Throws on an unknown id. */
export function designTree(id: string): SourceTree {
  const design = DESIGNS.get(id);
  if (!design) throw new Error(`no procedural model "${id}"`);
  return design.build().sourceTree(design.id, design.title);
}

/** Thrown when one or more designs would flicker; the message lists every overlap. */
export class ZFightingError extends Error {
  constructor(readonly found: ReadonlyMap<string, CoplanarOverlap[]>) {
    super(
      [
        "z-fighting faces (coplanar surfaces of different materials) - the model would flicker:",
        ...[...found].flatMap(([id, overlaps]) =>
          overlaps.map((o) =>
            `  ${id}: ${o.materials.join(" vs ")} on the plane n=(${o.normal.map((c) => c.toFixed(2)).join(", ")}) d=${o.offset.toFixed(2)}, ${o.area.toFixed(2)} m2`,
          ),
        ),
        "Give the shared surface one owner (see docs/models/skyscrapers.md, \"Flicker\").",
      ].join("\n"),
    );
    this.name = "ZFightingError";
  }
}

/** Every design's GLB bytes, after checking none of them z-fights. */
function buildAll(designs: readonly ProceduralDesign[]): Array<{ design: ProceduralDesign; bytes: Uint8Array; triangles: number; tree: SourceTree; rig: VehicleRig | null }> {
  const built = designs.map((design) => {
    const model = design.build();
    return {
      design,
      bytes: toGlb(design.id, model),
      triangles: model.triangleCount(),
      tree: model.sourceTree(design.id, design.title),
      rig: model.rig,
    };
  });
  const found = new Map<string, CoplanarOverlap[]>();
  for (const b of built) {
    const overlaps = findCoplanarOverlaps(b.bytes);
    if (overlaps.length) found.set(b.design.id, overlaps);
  }
  if (found.size) throw new ZFightingError(found);
  return built;
}

export interface GeneratedModel {
  id: string;
  glb: string; // absolute path
  thumb: string; // absolute path
  tree: string; // absolute path
  triangles: number;
  /** The model's rig (rig.ts), or null. */
  rig: VehicleRig | null;
  /** False when the GLB came out byte-identical to the one already on disk. */
  changed: boolean;
}

/**
 * Builds every design's GLB, thumbnail and source tree into `dir`/glb,
 * `dir`/thumbs and `dir`/tree. The thumbnail is only re-rendered when the GLB's
 * bytes changed or the PNG is missing, and a tree file is only rewritten when
 * its text changed; files of designs that no longer exist are removed. Throws a
 * ZFightingError, writing nothing, when any design would flicker.
 */
export function generateModels(
  dir = EXPORT_DIR,
  designs: readonly ProceduralDesign[] = [...DESIGNS.values()],
): GeneratedModel[] {
  const built = buildAll(designs); // throws before anything touches the disk
  const known = new Set(designs.map((d) => d.id));
  const glbDir = path.join(dir, "glb");
  const thumbDir = path.join(dir, "thumbs");
  const treeDir = path.join(dir, TREE_DIR);
  fs.mkdirSync(glbDir, { recursive: true });
  fs.mkdirSync(thumbDir, { recursive: true });
  fs.mkdirSync(treeDir, { recursive: true });
  const out: GeneratedModel[] = [];
  for (const { design, bytes, triangles, tree: sourceTree, rig } of built) {
    const glb = path.join(glbDir, `${design.id}.glb`);
    const thumb = path.join(thumbDir, `${design.id}.png`);
    const tree = path.join(treeDir, `${design.id}.json`);
    const treeText = `${JSON.stringify(sourceTree)}\n`;
    if (!fs.existsSync(tree) || fs.readFileSync(tree, "utf8") !== treeText) fs.writeFileSync(tree, treeText);
    const old = fs.existsSync(glb) ? fs.readFileSync(glb) : null;
    const changed = !old || !Buffer.from(bytes).equals(old);
    if (changed) fs.writeFileSync(glb, bytes);
    if (changed || !fs.existsSync(thumb)) {
      fs.writeFileSync(thumb, PNG.sync.write(renderGlbThumb(glb, THUMB_SIZE)));
    }
    out.push({ id: design.id, glb, thumb, tree, triangles, rig, changed });
  }
  for (const [sub, ext] of [[glbDir, ".glb"], [thumbDir, ".png"], [treeDir, ".json"]] as const) {
    for (const name of fs.readdirSync(sub)) {
      if (name.endsWith(ext) && !known.has(name.slice(0, -ext.length))) fs.rmSync(path.join(sub, name));
    }
  }
  return out;
}

/**
 * Writes `dir`/js/<id>.js for every design (a file is rewritten only when its
 * text changed) and removes the files of designs that no longer exist. Returns
 * each file's text by id.
 */
export async function generateJsModels(
  dir = EXPORT_DIR,
  designs: readonly ProceduralDesign[] = [...DESIGNS.values()],
): Promise<Map<string, string>> {
  const jsDir = path.join(dir, JS_DIR);
  fs.mkdirSync(jsDir, { recursive: true });
  const out = new Map<string, string>();
  for (const design of designs) {
    const source = DESIGN_SOURCE.get(design.id);
    if (!source) throw new Error(`no source module for design "${design.id}"`);
    const text = `${await bundleDesign(design, source)}`;
    writeIfChanged(path.join(jsDir, `${design.id}.js`), text);
    out.set(design.id, text);
  }
  for (const name of fs.readdirSync(jsDir)) {
    if (name.endsWith(".js") && !out.has(name.slice(0, -3))) fs.rmSync(path.join(jsDir, name));
  }
  return out;
}

/** Every file under `dir`, as sorted forward-slash paths relative to it. */
function listFiles(dir: string): string[] {
  if (!fs.existsSync(dir)) return [];
  return fs
    .readdirSync(dir, { recursive: true, encoding: "utf8" })
    .map((p) => p.split(path.sep).join("/"))
    .filter((p) => fs.statSync(path.join(dir, p)).isFile())
    .sort();
}

/**
 * Copies each design's source images (assets/<references>/, any depth, the
 * REFERENCE_EXTENSIONS) to `dir`/refs/<id>/, rewriting a file only when its
 * bytes changed, and removes every other file under `dir`/refs. Returns each
 * design's images in name order; a design without references gets none.
 */
export function generateReferences(
  dir = EXPORT_DIR,
  designs: readonly ProceduralDesign[] = [...DESIGNS.values()],
  assetsDir = ASSETS_DIR,
): Map<string, ReferenceImage[]> {
  const refsDir = path.join(dir, REFS_DIR);
  const out = new Map<string, ReferenceImage[]>();
  const keep = new Set<string>();
  for (const design of designs) {
    const images: ReferenceImage[] = [];
    if (design.references) {
      const src = path.join(assetsDir, design.references);
      for (const name of listFiles(src)) {
        if (!REFERENCE_EXTENSIONS.some((ext) => name.toLowerCase().endsWith(ext))) continue;
        const bytes = fs.readFileSync(path.join(src, name));
        const rel = `${design.id}/${name}`;
        const target = path.join(refsDir, rel);
        fs.mkdirSync(path.dirname(target), { recursive: true });
        if (!fs.existsSync(target) || !bytes.equals(fs.readFileSync(target))) fs.writeFileSync(target, bytes);
        keep.add(rel);
        images.push({ name, url: `${REFS_DIR}/${rel}`, bytes: bytes.length });
      }
    }
    out.set(design.id, images);
  }
  for (const rel of listFiles(refsDir)) if (!keep.has(rel)) fs.rmSync(path.join(refsDir, rel));
  // empty folders left by removed files, deepest first
  const dirs = fs.existsSync(refsDir) ? fs.readdirSync(refsDir, { recursive: true, encoding: "utf8" }) : [];
  for (const sub of dirs.sort().reverse()) {
    const p = path.join(refsDir, sub);
    if (fs.statSync(p).isDirectory() && fs.readdirSync(p).length === 0) fs.rmdirSync(p);
  }
  return out;
}

/** The whole export: the models, then the two meta.json files and the site's catalog.json. */
export async function buildExport(dir = EXPORT_DIR): Promise<{ models: GeneratedModel[]; catalog: ModelCatalog; js: Map<string, string> }> {
  const models = generateModels(dir);
  const js = await generateJsModels(dir);
  const refs = generateReferences(dir);
  const designs = [...DESIGNS.values()];
  fs.writeFileSync(path.join(dir, META_FILE), `${JSON.stringify(exportMeta(BUILDINGS), null, 2)}\n`);
  fs.writeFileSync(path.join(dir, VILLAGE_META_FILE), `${JSON.stringify(exportMeta(VILLAGE_HOUSES), null, 2)}\n`);
  const rigs = new Map(models.flatMap((m) => (m.rig ? [[m.id, m.rig] as const] : [])));
  fs.writeFileSync(path.join(dir, VEHICLE_META_FILE), `${JSON.stringify(exportVehicleMeta(ALL_VEHICLES, rigs), null, 2)}\n`);
  const catalog: ModelCatalog = {
    version: 1,
    records: designs.map((design) => {
      const built = models.find((m) => m.id === design.id)!;
      const bytes = fs.readFileSync(built.glb);
      const stats = glbStats(bytes);
      const fields = design.catalog ?? (VEHICLE_IDS.has(design.id) ? VEHICLE_CATALOG : SKYSCRAPER_CATALOG);
      const jsText = js.get(design.id)!;
      return catalogRecord(metaEntry(design, fields, built.rig), {
        ...stats,
        glbBytes: bytes.length,
        glbGzipBytes: gzipSize(bytes),
        jsBytes: Buffer.byteLength(jsText),
        jsGzipBytes: gzipSize(jsText),
        thumbBytes: fs.statSync(built.thumb).size,
      }, refs.get(design.id));
    }),
  };
  fs.writeFileSync(path.join(dir, CATALOG_FILE), `${JSON.stringify(catalog, null, 2)}\n`);
  return { models, catalog, js };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  let models: GeneratedModel[];
  let catalog: ModelCatalog;
  try {
    ({ models, catalog } = await buildExport());
  } catch (e) {
    if (!(e instanceof ZFightingError)) throw e;
    console.error(e.message);
    process.exit(1);
  }
  for (const m of models) {
    console.log(`${m.id.padEnd(24)} ${String(m.triangles).padStart(5)} tris ${m.changed ? "(written)" : "(unchanged)"}`);
  }
  console.log(`\n${"model".padEnd(24)} ${"GLB".padStart(9)} ${"GLB gz".padStart(8)} ${"JS".padStart(8)} ${"JS gz".padStart(8)}`);
  for (const r of catalog.records) {
    const kb = (n: number): string => `${(n / 1024).toFixed(1)} KB`.padStart(9);
    console.log(`${r.id.padEnd(24)} ${kb(r.glbBytes)} ${kb(r.glbGzipBytes)} ${kb(r.jsBytes)} ${kb(r.jsGzipBytes)}`);
  }
  console.log(`\nExport: ${path.relative(process.cwd(), EXPORT_DIR) || "."} (${models.length} models)`);
}
